const items = $input.all();

// Verifica se há dados válidos
if (!items || items.length === 0 || !items[0].json.numero) {
  return [{ json: { mensagem_final: '💈 *Painel de Pausas*\n\nNenhum cliente em pausa no momento.' } }];
}

// Cabeçalho da nossa "tabela"
let mensagem = '💈 *PAINEL DE PAUSAS - BARBEARIA* \n *Só me avisar por aqui para remover o pause se precisar*';
mensagem += '➖➖➖➖➖➖➖➖➖➖➖➖\n\n';

const lista = items.map(function(item) {
  const j = item.json;

  // Trata o nome e o número
  const nome = j.nome || 'Sem nome';
  const tel = String(j.numero).trim().replace(/^55/, '');

  // Trata e formata a data e hora do banco (Convertendo de UTC para Horário de Brasília)
  let dataFormatada = 'Data desconhecida';
  if (j.criado_em) {
    const dataObj = new Date(j.criado_em);
    dataFormatada = dataObj.toLocaleString('pt-BR', { 
        timeZone: 'America/Sao_Paulo', 
        day: '2-digit', 
        month: '2-digit', 
        year: 'numeric', 
        hour: '2-digit', 
        minute: '2-digit' 
    }).replace(',', ' às'); // Troca a vírgula padrão por " às "
  }

  // Monta o "card" de cada cliente
  return `👤 *Cliente:* ${nome}\n📱 *Número:* ${tel}\n🕒 *Pausado:* ${dataFormatada}\n➖➖➖➖➖➖➖➖➖➖➖➖`;
}).join('\n\n');

return [{ json: { mensagem_final: mensagem + lista } }];

